async function exportAll(){const zip=new JSZip(),links=[],files=[];const wordBlob=await buildTextDocx();zip.file('01_Текстові_матеріали.docx',wordBlob);for(const section of publishedSections()){for(const block of(section.blocks||[])){const a=answerFor(section,block)||{};if(block.type==='table'){const cols=block.columns||[],rows=a.rows||[];const csv='\uFEFF'+[cols,...rows].map(r=>r.map(v=>`"${String(v||'').replace(/"/g,'""')}"`).join(';')).join('\r\n');zip.file(`02_Таблиці/${safeFileName(section.title)}_${safeFileName(block.title)}.csv`,csv)}else if(block.type==='file'){for(const f of(a.files||[]))files.push(`${section.title}  -  ${block.title}: ${f.name}  -  ${f.url}`)}else if(block.type==='link'){const v=String(a.value||'').trim();if(v)links.push(`${block.title}: ${v}`)}}}zip.file('03_Посилання.txt',links.join('\n'));zip.file('04_Прикріплені_файли.txt',files.join('\n'));const blob=await zip.generateAsync({type:'blob'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`${safeFileName(work.name)}_режисерська_лабораторія.zip`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1500)}
function openTheoryModal(btn){const modal=appEl.querySelector('#theoryModal');if(!modal)return;appEl.querySelector('#theoryModalTitle').textContent=btn.dataset.theoryTitle||'Теоретичний матеріал';appEl.querySelector('#theoryModalCopy').innerHTML=rich(btn.dataset.theory||'');modal.classList.add('open');modal.setAttribute('aria-hidden','false');document.body.classList.add('modal-open')}function closeTheoryModal(){const modal=appEl.querySelector('#theoryModal');if(!modal)return;modal.classList.remove('open');modal.setAttribute('aria-hidden','true');document.body.classList.remove('modal-open')}

async function buildSummaryDocx(){const s=schema.sections.find(x=>x.id==='choice-justification');const b=s?.blocks?.find(x=>x.id==='choiceSummary');const txt=String(answerFor(s,b)?.value||'').trim();if(!txt)throw new Error('Підсумкове обґрунтування ще не заповнене.');const p=txt.split(/\n+/).filter(Boolean).map(x=>`<w:p><w:pPr><w:jc w:val="both"/><w:spacing w:line="360" w:lineRule="auto"/><w:ind w:firstLine="709"/></w:pPr><w:r><w:rPr><w:rFonts w:ascii="Times New Roman" w:hAnsi="Times New Roman"/><w:sz w:val="28"/></w:rPr><w:t xml:space="preserve">${xmlEsc(x)}</w:t></w:r></w:p>`).join('');const documentXml=`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body><w:p><w:pPr><w:jc w:val="center"/></w:pPr><w:r><w:rPr><w:b/><w:rFonts w:ascii="Times New Roman" w:hAnsi="Times New Roman"/><w:sz w:val="28"/></w:rPr><w:t>ПІДСУМКОВЕ ОБҐРУНТУВАННЯ ВИБОРУ ПРОЄКТУ</w:t></w:r></w:p><w:p><w:r><w:rPr><w:rFonts w:ascii="Times New Roman" w:hAnsi="Times New Roman"/><w:sz w:val="28"/></w:rPr><w:t>${xmlEsc(work.name||'')}</w:t></w:r></w:p><w:p><w:pPr><w:jc w:val="center"/></w:pPr><w:r><w:rPr><w:rFonts w:ascii="Times New Roman" w:hAnsi="Times New Roman"/><w:sz w:val="28"/></w:rPr><w:t>${xmlEsc(projectDisplayLabel())}</w:t></w:r></w:p>${p}<w:sectPr><w:pgSz w:w="11906" w:h="16838"/><w:pgMar w:top="1134" w:right="567" w:bottom="1134" w:left="1701"/></w:sectPr></w:body></w:document>`;const ct=`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/></Types>`;const rels=`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>`;const z=new JSZip();z.file('[Content_Types].xml',ct);z.folder('_rels').file('.rels',rels);z.folder('word').file('document.xml',documentXml);return z.generateAsync({type:'blob',mimeType:'application/vnd.openxmlformats-officedocument.wordprocessingml.document'})}
async function downloadSummaryWord(){try{const blob=await buildSummaryDocx();const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`${safeFileName(work.name)}_Підсумкове_обґрунтування.docx`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1500)}catch(e){alert(e.message||'Не вдалося сформувати Word.')}}
function currentSectionAnswers(sectionId){const section=schema.sections.find(x=>x.id===sectionId);if(!section)return{};const box=appEl.querySelector(`[data-section="${CSS.escape(sectionId)}"]`);if(box){try{return collectSection(sectionId)}catch(e){console.warn('Export uses saved answers:',e)}}const out={};for(const block of(section.blocks||[]))out[block.id]=answerFor(section,block)||{};return out}
function standaloneDocxContext(){return{rels:[],nextId:3}}
function standaloneLinkPara(ctx,label,url){const clean=String(url||'').trim();if(!clean)return'';const rid=`rId${ctx.nextId++}`;ctx.rels.push({rid,url:clean});return `<w:p><w:pPr><w:jc w:val="left"/><w:spacing w:before="0" w:after="80" w:line="360" w:lineRule="auto"/></w:pPr>${docxRun(label+' ',{bold:true})}<w:hyperlink r:id="${rid}" w:history="1"><w:r><w:rPr><w:rFonts w:ascii="Times New Roman" w:hAnsi="Times New Roman" w:eastAsia="Times New Roman"/><w:sz w:val="28"/><w:szCs w:val="28"/><w:color w:val="0563C1"/><w:u w:val="single"/></w:rPr><w:t xml:space="preserve">${xmlEsc(clean)}</w:t></w:r></w:hyperlink></w:p>`}
function standaloneText(paras,text,{bold=false,heading=false}={}){const value=String(text||'').trim();if(!value)return false;if(heading){paras.push(docxPara(value,{bold:true,firstLine:false,spaceBefore:180,spaceAfter:100}));return true}value.split(/\n+/).map(x=>x.trim()).filter(Boolean).forEach(x=>paras.push(docxPara(x,{bold,firstLine:!bold,spaceAfter:80})));return true}
async function buildStandaloneDocx(title,bodyBuilder){const ctx=standaloneDocxContext(),paras=[];paras.push(docxTitlePara(title));paras.push(docxTitlePara(work.name||'Студент',true));if(work.group)paras.push(docxTitlePara(work.group,true));paras.push(docxTitlePara(projectDisplayLabel()||'Індивідуальний режисерський проєкт',true));paras.push('<w:p><w:pPr><w:spacing w:after="120"/></w:pPr></w:p>');bodyBuilder(paras,ctx);const documentXml=`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><w:body>${paras.join('')}<w:sectPr><w:headerReference w:type="default" r:id="rId1"/><w:pgSz w:w="11906" w:h="16838"/><w:pgMar w:top="1134" w:right="567" w:bottom="1134" w:left="1701" w:header="567" w:footer="567" w:gutter="0"/><w:cols w:space="708"/><w:docGrid w:linePitch="360"/></w:sectPr></w:body></w:document>`;const styles=`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:styles xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:docDefaults><w:rPrDefault><w:rPr><w:rFonts w:ascii="Times New Roman" w:hAnsi="Times New Roman" w:eastAsia="Times New Roman"/><w:sz w:val="28"/><w:szCs w:val="28"/><w:color w:val="000000"/></w:rPr></w:rPrDefault><w:pPrDefault><w:pPr><w:jc w:val="both"/><w:ind w:firstLine="709"/><w:spacing w:line="360" w:lineRule="auto"/></w:pPr></w:pPrDefault></w:docDefaults></w:styles>`;const header=`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:hdr xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:p><w:pPr><w:jc w:val="right"/></w:pPr><w:r><w:rPr><w:rFonts w:ascii="Times New Roman" w:hAnsi="Times New Roman"/><w:sz w:val="24"/></w:rPr><w:fldChar w:fldCharType="begin"/></w:r><w:r><w:instrText xml:space="preserve"> PAGE </w:instrText></w:r><w:r><w:fldChar w:fldCharType="end"/></w:r></w:p></w:hdr>`;const contentTypes=`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/><Override PartName="/word/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.styles+xml"/><Override PartName="/word/header1.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.header+xml"/><Override PartName="/docProps/core.xml" ContentType="application/vnd.openxmlformats-package.core-properties+xml"/><Override PartName="/docProps/app.xml" ContentType="application/vnd.openxmlformats-officedocument.extended-properties+xml"/></Types>`;const rels=`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/package/2006/relationships/metadata/core-properties" Target="docProps/core.xml"/><Relationship Id="rId3" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/extended-properties" Target="docProps/app.xml"/></Relationships>`;const hyperlinkRels=ctx.rels.map(x=>`<Relationship Id="${x.rid}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/hyperlink" Target="${xmlEsc(x.url)}" TargetMode="External"/>`).join('');const docRels=`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/header" Target="header1.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/>${hyperlinkRels}</Relationships>`;const now=new Date().toISOString(),core=`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><cp:coreProperties xmlns:cp="http://schemas.openxmlformats.org/package/2006/metadata/core-properties" xmlns:dc="http://purl.org/dc/elements/1.1/" xmlns:dcterms="http://purl.org/dc/terms/" xmlns:dcmitype="http://purl.org/dc/dcmitype/" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"><dc:title>${xmlEsc(title)} - ${xmlEsc(work.name||'')}</dc:title><dc:creator>REMS Control</dc:creator><dcterms:created xsi:type="dcterms:W3CDTF">${now}</dcterms:created><dcterms:modified xsi:type="dcterms:W3CDTF">${now}</dcterms:modified></cp:coreProperties>`,appXml=`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Properties xmlns="http://schemas.openxmlformats.org/officeDocument/2006/extended-properties" xmlns:vt="http://schemas.openxmlformats.org/officeDocument/2006/docPropsVTypes"><Application>REMS Control</Application></Properties>`;const z=new JSZip();z.file('[Content_Types].xml',contentTypes);z.folder('_rels').file('.rels',rels);z.folder('word').file('document.xml',documentXml).file('styles.xml',styles).file('header1.xml',header);z.folder('word').folder('_rels').file('document.xml.rels',docRels);z.folder('docProps').file('core.xml',core).file('app.xml',appXml);return z.generateAsync({type:'blob',mimeType:'application/vnd.openxmlformats-officedocument.wordprocessingml.document'})}
function triggerBlobDownload(blob,filename){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1500)}
async function downloadProjectParametersWord(){try{const section=schema.sections.find(x=>x.id==='project-parameters'),answers=currentSectionAnswers('project-parameters');const blob=await buildStandaloneDocx('1.2. ВИХІДНІ ПАРАМЕТРИ ПРОЄКТУ',(paras)=>{for(const block of(section?.blocks||[])){if(['theory','logic_chain','material_collection'].includes(block.type))continue;const a=answers[block.id]||{};let value=block.type==='checklist'?(a.values||[]).join(', '):String(a.value||'').trim();paras.push(docxPara(block.title||'Пункт',{bold:true,firstLine:false,spaceBefore:160,spaceAfter:80}));if(value)standaloneText(paras,value);else paras.push(docxPara('Не заповнено',{firstLine:false,spaceAfter:80}));}});triggerBlobDownload(blob,`${safeFileName(work.name)}_1.2_Вихідні_параметри.docx`)}catch(e){console.error(e);alert(e.message||'Не вдалося сформувати Word.')}}
async function downloadIdeologicalWord(){try{const section=schema.sections.find(x=>x.id==='ideological-analysis'),answers=currentSectionAnswers('ideological-analysis');const blob=await buildStandaloneDocx('1.4. ІДЕЙНО-ТЕМАТИЧНИЙ АНАЛІЗ',(paras)=>{for(const block of(section?.blocks||[])){if(block.type==='logic_chain'||block.type==='theory')continue;const a=answers[block.id]||{};if(block.type==='conflict_builder'){const parts=[['Зміст конфлікту: що з чим стикається?',a.content],['Сторона А: хто або що представляє цю сторону?',a.sideA?.name],['Сторона А: чого вона прагне і що відстоює?',a.sideA?.goal],['Сторона А: через що розкриваємо цю сторону?',a.sideA?.manifestations],['Предмет конфлікту: за що відбувається боротьба?',a.subject],['Сторона Б: хто або що представляє цю сторону?',a.sideB?.name],['Сторона Б: чого вона прагне і що відстоює?',a.sideB?.goal],['Сторона Б: через що розкриваємо цю сторону?',a.sideB?.manifestations],['Формулювання головного конфлікту',a.summary||a.value]];paras.push(docxPara(block.title||'1.4.5. Конфлікт',{bold:true,firstLine:false,spaceBefore:180,spaceAfter:100}));for(const [label,value] of parts){paras.push(docxPara(label,{bold:true,firstLine:false,spaceBefore:100,spaceAfter:60}));if(String(value||'').trim())standaloneText(paras,value);else paras.push(docxPara('Не заповнено',{firstLine:false,spaceAfter:60}))}continue}paras.push(docxPara(block.title||'Пункт',{bold:true,firstLine:false,spaceBefore:160,spaceAfter:80}));const value=String(a.value||'').trim();if(value)standaloneText(paras,value);else paras.push(docxPara('Не заповнено',{firstLine:false,spaceAfter:80}));}});triggerBlobDownload(blob,`${safeFileName(work.name)}_1.4_Ідейно-тематичний_аналіз.docx`)}catch(e){console.error(e);alert(e.message||'Не вдалося сформувати Word.')}}
async function downloadResearchWord(kind){try{const section=schema.sections.find(x=>x.id==='research-materials'),block=section?.blocks?.find(x=>x.collectionKind===kind);if(!block)throw new Error('Не знайдено потрібний блок матеріалів.');const answers=currentSectionAnswers('research-materials'),items=Array.isArray(answers[block.id]?.items)?answers[block.id].items:[];const title=kind==='documentary'?'1.3.1. ДОКУМЕНТАЛЬНІ МАТЕРІАЛИ':kind==='artistic'?'1.3.2. ХУДОЖНІ МАТЕРІАЛИ':'1.3.3. РЕЖИСЕРСЬКИЙ БЛОКНОТ';const blob=await buildStandaloneDocx(title,(paras,ctx)=>{if(!items.length){paras.push(docxPara(kind==='notes'?'Нотаток ще немає.':'Матеріалів ще немає.',{firstLine:false}));return}items.forEach((item,idx)=>{paras.push(docxPara(`${idx+1}. ${String(item.title||'Без назви').trim()||'Без назви'}`,{bold:true,firstLine:false,spaceBefore:180,spaceAfter:100}));if(kind==='notes'){if(String(item.directorNote||'').trim()){paras.push(docxPara('Нотатка',{bold:true,firstLine:false,spaceAfter:60}));standaloneText(paras,item.directorNote)}else paras.push(docxPara('Нотатка не заповнена',{firstLine:false,spaceAfter:80}))}else{paras.push(docxPara('Що в цьому важливого?',{bold:true,firstLine:false,spaceAfter:60}));if(String(item.description||'').trim())standaloneText(paras,item.description);else paras.push(docxPara('Не заповнено',{firstLine:false,spaceAfter:80}));paras.push(docxPara('Як це можна використати?',{bold:true,firstLine:false,spaceAfter:60}));if(String(item.directorNote||'').trim())standaloneText(paras,item.directorNote);else paras.push(docxPara('Не заповнено',{firstLine:false,spaceAfter:80}))}const urls=[...(Array.isArray(item.links)?item.links:[]),item.link].map(x=>String(x||'').trim()).filter(Boolean).filter((v,i,a)=>a.indexOf(v)===i);urls.forEach((u,i)=>paras.push(standaloneLinkPara(ctx,`Посилання ${i+1}:`,u)));(Array.isArray(item.files)?item.files:[]).forEach((f,i)=>{if(String(f?.url||'').trim())paras.push(standaloneLinkPara(ctx,`Файл ${i+1}${f?.name?` (${f.name})`:''}:`,f.url))});});});const suffix=kind==='documentary'?'1.3.1_Документальні_матеріали':kind==='artistic'?'1.3.2_Художні_матеріали':'1.3.3_Режисерський_блокнот';triggerBlobDownload(blob,`${safeFileName(work.name)}_${suffix}.docx`)}catch(e){console.error(e);alert(e.message||'Не вдалося сформувати Word.')}}
async function downloadScenarioDramaturgyWord(){try{const section=schema.sections.find(x=>x.id==='scenario-dramaturgy'),answers=currentSectionAnswers('scenario-dramaturgy');const blob=await buildStandaloneDocx('2. СЦЕНАРНО-ДРАМАТУРГІЧНА ОСНОВА',(paras)=>{for(const block of(section?.blocks||[])){if(block.type==='logic_chain'||block.type==='theory')continue;const a=answers[block.id]||{};paras.push(docxPara(block.title||'Пункт',{bold:true,firstLine:false,spaceBefore:180,spaceAfter:80}));if(block.type==='table'){const rows=Array.isArray(a.rows)?a.rows:[],cols=block.columns||[];if(!rows.length||!rows.some(r=>r.some(v=>String(v||'').trim()))){paras.push(docxPara('Не заповнено',{firstLine:false,spaceAfter:80}));continue}rows.forEach((row,ri)=>{if(!row.some(v=>String(v||'').trim()))return;paras.push(docxPara(`Запис ${ri+1}`,{bold:true,firstLine:false,spaceBefore:120,spaceAfter:60}));cols.forEach((col,ci)=>{const v=String(row[ci]||'').trim();if(!v)return;paras.push(docxPara(String(col||`Поле ${ci+1}`),{bold:true,firstLine:false,spaceBefore:60,spaceAfter:40}));standaloneText(paras,v)})});continue}const value=String(a.value||'').trim();if(value)standaloneText(paras,value);else paras.push(docxPara('Не заповнено',{firstLine:false,spaceAfter:80}))}});triggerBlobDownload(blob,`${safeFileName(work.name)}_Розділ_2_Сценарно-драматургічна_основа.docx`)}catch(e){console.error(e);alert(e.message||'Не вдалося сформувати Word.')}}
function sectionExportTools(sectionId){if(sectionId==='project-parameters')return'<div class="section-export-tools"><button type="button" class="section-word-btn" data-export-parameters>W Завантажити 1.2 у Word</button></div>';if(sectionId==='research-materials')return'<div class="section-export-tools research-export-tools"><button type="button" class="section-word-btn" data-export-research="documentary">W Документальні</button><button type="button" class="section-word-btn" data-export-research="artistic">W Художні</button><button type="button" class="section-word-btn" data-export-research="notes">W Блокнот</button></div>';if(sectionId==='ideological-analysis')return'<div class="section-export-tools"><button type="button" class="section-word-btn" data-export-ideological>W Завантажити 1.4 у Word</button></div>';if(sectionId==='scenario-dramaturgy')return'<div class="section-export-tools"><button type="button" class="section-word-btn" data-export-scenario-dramaturgy>W Завантажити розділ 2 у Word</button></div>';return''}

function setupSectionObserver(){const navs=[...appEl.querySelectorAll('[data-nav-section]')],sectionsEls=[...appEl.querySelectorAll('.section-card[data-section]')];if(!sectionsEls.length)return;const obs=new IntersectionObserver(entries=>{const visible=entries.filter(e=>e.isIntersecting).sort((a,b)=>b.intersectionRatio-a.intersectionRatio)[0];if(!visible)return;const id=visible.target.dataset.section;navs.forEach(n=>n.classList.toggle('active',n.dataset.navSection===id))},{rootMargin:'-30% 0px -58% 0px',threshold:[0,.1,.3,.5]});sectionsEls.forEach(s=>obs.observe(s))}

function bind(){
 appEl.querySelectorAll('[data-theory]').forEach(b=>b.onclick=()=>openTheoryModal(b));
 appEl.querySelectorAll('[data-nav-section]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();const target=appEl.querySelector(`#section-${CSS.escape(a.dataset.navSection)}`);if(!target)return;const topbar=document.querySelector('.lab-topbar');const sticky=appEl.querySelector('.sticky-sections');const offset=(topbar?.offsetHeight||0)+(sticky?.offsetHeight||0)+14;const y=target.getBoundingClientRect().top+window.scrollY-offset;window.scrollTo({top:Math.max(0,y),behavior:'smooth'});}));
 appEl.querySelectorAll('[data-export-summary]').forEach(b=>b.onclick=downloadSummaryWord);
 appEl.querySelectorAll('[data-export-parameters]').forEach(b=>b.onclick=downloadProjectParametersWord);
 appEl.querySelectorAll('[data-export-ideological]').forEach(b=>b.onclick=downloadIdeologicalWord);
 appEl.querySelectorAll('[data-export-scenario-dramaturgy]').forEach(b=>b.onclick=downloadScenarioDramaturgyWord);
 appEl.querySelectorAll('[data-export-research]').forEach(b=>b.onclick=()=>downloadResearchWord(b.dataset.exportResearch));
 appEl.querySelector('#studentMessagesBtn')?.addEventListener('click',openStudentMessagesModal);
 appEl.querySelectorAll('[data-resubmit-item]').forEach(b=>b.onclick=()=>submitItemCorrection(b.dataset.resubmitItem,b.dataset.resubmitSection,b));appEl.querySelectorAll('[data-open-student-thread]').forEach(b=>b.onclick=e=>{e.preventDefault();e.stopPropagation();openStudentThreadModal(b.dataset.openStudentThread)});
 setupSectionObserver();
 const wireMaterialCard=card=>{card.querySelector('[data-remove-material]')?.addEventListener('click',()=>card.remove());card.querySelectorAll('[data-remove-link]').forEach(b=>b.onclick=()=>{const row=b.closest('.material-link-entry'),wrap=b.closest('[data-material-links]');if(wrap?.querySelectorAll('.material-link-entry').length>1)row?.remove();else{const inp=row?.querySelector('input');if(inp)inp.value=''}});card.querySelector('[data-add-link]')?.addEventListener('click',e=>{const wrap=e.currentTarget.closest('[data-material-links]');if(!wrap)return;const row=document.createElement('div');row.className='material-link-entry';row.innerHTML='<input data-mi-link placeholder="Вставте посилання: Google Drive, YouTube, сайт, стаття, архів…"><button type="button" class="material-link-remove" data-remove-link>×</button>';wrap.insertBefore(row,e.currentTarget);row.querySelector('[data-remove-link]').onclick=()=>row.remove()})};
 appEl.querySelectorAll('[data-add-material]').forEach(b=>b.onclick=()=>{const blockId=b.dataset.addMaterial,section=schema.sections.find(s=>(s.blocks||[]).some(x=>x.id===blockId)),block=section?.blocks?.find(x=>x.id===blockId),wrap=appEl.querySelector(`[data-material-collection="${CSS.escape(blockId)}"]`);wrap?.querySelector('.material-empty')?.remove();if(wrap&&block){const tmp=document.createElement('div');tmp.innerHTML=materialItemHtml(block,{id:crypto.randomUUID?.()||String(Date.now())});const card=tmp.firstElementChild;wrap.insertBefore(card,b);wireMaterialCard(card)}});
 appEl.querySelectorAll('[data-material-item]').forEach(wireMaterialCard);appEl.querySelectorAll('.section-card[data-section]').forEach(sec=>{let timer=null;const start=()=>{clearTimeout(timer);timer=setTimeout(()=>markSectionStarted(sec.dataset.section),650)};sec.addEventListener('input',start,{once:true});sec.addEventListener('change',start,{once:true})});appEl.querySelector('#backTop')?.addEventListener('click',()=>window.scrollTo({top:0,behavior:'smooth'}));appEl.querySelectorAll('[data-close-theory]').forEach(b=>b.onclick=closeTheoryModal);document.onkeydown=e=>{if(e.key==='Escape')closeTheoryModal()};appEl.querySelectorAll('[data-save]').forEach(b=>b.onclick=async()=>{b.disabled=true;await saveSection(b.dataset.save,false);setTimeout(()=>b.disabled=false,300)});appEl.querySelectorAll('[data-submit]').forEach(b=>b.onclick=async()=>{if(!confirm('Подати цей розділ викладачу на перевірку?'))return;b.disabled=true;await saveSection(b.dataset.submit,true);setTimeout(()=>b.disabled=false,300)});appEl.querySelectorAll('[data-research-complete]').forEach(b=>b.onclick=async()=>{b.disabled=true;await markResearchCollected();setTimeout(()=>b.disabled=false,300)});appEl.querySelectorAll('[data-add-row]').forEach(b=>b.onclick=()=>addTableRow(b.dataset.addRow));appEl.querySelectorAll('[data-file]').forEach(inp=>inp.onchange=async()=>{const f=inp.files?.[0];inp.value='';await uploadFile(inp.dataset.file,f)});appEl.querySelector('#exportWord')?.addEventListener('click',downloadWord);appEl.querySelector('#exportLab')?.addEventListener('click',exportAll)
}
async function loadSchema(){try{const s=await getDoc(schemaRef);schema=upgradeSchema(s.exists()?s.data():DEFAULT_SCHEMA)}catch(e){console.error(e);schema=upgradeSchema(DEFAULT_SCHEMA)}}
function normalizePhotoSrc(v){const x=String(v||'').trim();if(!x)return'';if(/^data:|^blob:|^https?:\/\//i.test(x))return x;if(x.startsWith('images/'))return `https://rems-44.github.io/REMS-44/${encodeURI(x)}`;return x}
async function loadPhoto(){photo='';try{
 const candidates=[];if(work?.mediaId)candidates.push(String(work.mediaId));
 for(const id of candidates){const s=await getDoc(doc(db,'rems_student_media',id));if(s.exists()){photo=normalizePhotoSrc(s.data()?.photoData||s.data()?.photoUrl);if(photo)return}}
 if(work?.studentId){const qs=await getDocs(query(collection(db,'rems_student_media'),where('studentId','==',String(work.studentId)),limit(1)));if(!qs.empty){photo=normalizePhotoSrc(qs.docs[0].data()?.photoData||qs.docs[0].data()?.photoUrl);if(photo)return}}
 if(work?.mediaId){const ps=await getDoc(doc(db,'rems_public_profiles',String(work.mediaId)));if(ps.exists()){photo=normalizePhotoSrc(ps.data()?.photo||ps.data()?.photoData);if(photo)return}}
 photo=normalizePhotoSrc(work?.photoUrl||'');
 }catch(e){console.error('Photo',e)}}
await loadSchema();
onSnapshot(workRef,async snap=>{if(!snap.exists()){fail('Лабораторію ще не активовано','Попроси викладача активувати персональний доступ у REMS-Control.');return}work=snap.data()||{};await loadPhoto();render()},err=>{console.error(err);fail('Не вдалося відкрити лабораторію','Перевір посилання та інтернет-з’єднання.')});
onSnapshot(feedbackRef,snap=>{feedback=snap.exists()?snap.data()||{}:{};if(work){render()}},err=>{console.error('Feedback:',err);feedback={};if(work)render()});

